function bottomUpTree($depth)
{
    $node = new TreeNode();

    if ($depth > 0) {
        --$depth;
        $node->left = bottomUpTree($depth);
        $node->right = bottomUpTree($depth);
    }

    return $node;
}

function itemCheck($node)
{
    if ($node->left === null) {
        return 1;
    }

    return 1 + itemCheck($node->left) + itemCheck($node->right);
